import template from './store-credits-index.html.twig';
import "./store-credits-index.scss";
import '../../components/sw-customer-grid';

const { Component, Mixin } = Shopware;
const { Criteria } = Shopware.Data;

Component.register('store-credits-index', {
    template,

    inject: ['repositoryFactory', 'storeCreditApiService', 'acl'],

    mixins: [
        Mixin.getByName('notification'),
        Mixin.getByName('listing'),
    ],

    data() {
        return {
            confirmDeleteModalVisible: false,
            addBalanceModalVisible: false,
            deductBalanceModalVisible: false,
            addCustomerModalVisible: false,
            repository: null,
            storeCredits: [],
            customers: [],
            isLoading: false,
            isSaving: false,
            amount: 0,
            reason: '',
            selectedCustomer: null,
            selectedNewCustomer: null,
            selectedStoreCredit: null,
            newCustomerAmount: 0,
            total: 0,
            term: '',
            columns: [
                { property: 'customerFullName', label: 'Customer Full Name', allowResize: true, sortable: false },
                { property: 'balance', label: 'Balance', allowResize: true, sortable: false },
                {
                    property: 'actions',
                    label: 'Balance Actions',
                    allowResize: false,
                    align: 'center',
                    sortable: false,
                    width: '300px',
                },
            ],
        };
    },

    created() {
        this.repository = this.repositoryFactory.create('solu1_store_credit');

        // Initialize page and limit from URL query parameters
        if (this.$route.query.page) {
            this.page = parseInt(this.$route.query.page, 10) || 1;
        }
        if (this.$route.query.limit) {
            this.limit = parseInt(this.$route.query.limit, 10) || 10;
        }
        if (this.$route.query.term) {
            this.term = String(this.$route.query.term);
        }

        this.fetchStoreCredits();
    },

    watch: {
        '$route.query.page'() {
            if (this.$route.query.page) {
                this.page = parseInt(this.$route.query.page, 10);
                this.fetchStoreCredits();
            }
        },
        '$route.query.limit'() {
            if (this.$route.query.limit) {
                this.limit = parseInt(this.$route.query.limit, 10);
                this.fetchStoreCredits();
            }
        },
        '$route.query.term'(newTerm) {
            const term = newTerm ? String(newTerm) : '';
            if (term === this.term) {
                return;
            }
            this.term = term;
            this.page = 1;
            this.fetchStoreCredits();
        },
    },

    methods: {
        fetchStoreCredits() {
            this.isLoading = true;

            const criteria = new Criteria();
            criteria.setPage(this.page);
            criteria.setLimit(this.limit);
            criteria.addAssociation('customer');
            criteria.addAssociation('currency');
            criteria.addSorting(Criteria.sort('createdAt', 'DESC'));

            const searchTerm = (this.term || '').trim();
            if (searchTerm !== '') {
                criteria.addFilter(
                    Criteria.multi('OR', [
                        Criteria.contains('customer.firstName', searchTerm),
                        Criteria.contains('customer.lastName', searchTerm),
                        Criteria.contains('customer.email', searchTerm),
                        Criteria.contains('customer.customerNumber', searchTerm),
                    ]),
                );
            }

            return this.repository.search(criteria, Shopware.Context.api)
                .then((result) => {
                    this.storeCredits = result.map((credit) => {
                        const customer = credit.customer;
                        const firstName = customer?.firstName || '';
                        const lastName = customer?.lastName || '';
                        const customerFullName = (firstName + ' ' + lastName).trim() || 'N/A';

                        return {
                            id: credit.id,
                            customerFullName: customerFullName,
                            balance: credit.balance || 0,
                            currencyId: credit.currencyId,
                            currencyIsoCode: credit.currency?.isoCode || Shopware.Context.app.systemCurrencyISOCode || 'EUR',
                            customerId: credit.customerId,
                            storeCreditId: credit.id,
                        };
                    });
                    this.total = result.total || 0;
                })
                .catch((error) => {
                    console.error('Error fetching store credits:', error);
                    this.createNotificationError({
                        title: 'Error',
                        message: error.response?.data?.errors?.[0]?.detail || 'Failed to load store credits. Please refresh the page.',
                    });
                })
                .finally(() => {
                    this.isLoading = false;
                });
        },

        onSearch(searchTerm) {
            this.term = searchTerm ? String(searchTerm).trim() : '';
            this.page = 1;
            this.updateRouteQuery();
            this.fetchStoreCredits();
        },

        onPageChange({ page, limit }) {
            this.page = page;
            if (limit) {
                this.limit = limit;
            }
            this.updateRouteQuery();
        },

        onLimitChange(limit) {
            this.limit = limit;
            this.page = 1;
            this.updateRouteQuery();
        },

        updateRouteQuery() {
            const query = {
                page: this.page,
                limit: this.limit,
            };

            if (this.term) {
                query.term = this.term;
            }

            this.$router.push({
                name: this.$route.name,
                query,
            });
        },

        formatCurrency(value, currencyIsoCode = null) {
            const currency = currencyIsoCode || Shopware.Context.app.systemCurrencyISOCode || 'EUR';
            const locale = Shopware.Context.app.locale?.replace('_', '-') || 'en-US';
            return new Intl.NumberFormat(locale, {
                style: 'currency',
                currency: currency,
            }).format(value);
        },

        fetchCustomers() {
            const criteria = new Criteria();
            criteria.addSorting(Criteria.sort('lastName', 'ASC'));

            this.repositoryFactory.create('customer').search(criteria, Shopware.Context.api)
                .then((result) => {
                    this.customers = result.map(customer => ({
                        id: customer.id,
                        name: `${customer.firstName} ${customer.lastName}`,
                    }));
                })
                .catch((error) => {
                    console.error('Error fetching customers:', error);
                });
        },

        openAddBalanceModal(customer) {
            this.selectedCustomer = customer;
            this.amount = 0;
            this.reason = '';
            this.addBalanceModalVisible = true;
        },

        openDeductBalanceModal(customer) {
            this.selectedCustomer = customer;
            this.amount = 0;
            this.reason = '';
            this.deductBalanceModalVisible = true;
        },

        openAddCustomerModal() {
            this.selectedNewCustomer = null;
            this.newCustomerAmount = 0;
            this.addCustomerModalVisible = true;

        },

        addBalance() {
            return this.adjustBalance('add', this.selectedCustomer?.customerId, this.amount, this.reason, 'addBalanceModalVisible', this.selectedCustomer?.currencyId);
        },

        deductBalance() {
            return this.adjustBalance('deduct', this.selectedCustomer?.customerId, this.amount, this.reason, 'deductBalanceModalVisible', this.selectedCustomer?.currencyId);
        },

        addCustomerCredit() {
            return this.adjustBalance('add', this.selectedNewCustomer, this.newCustomerAmount, 'Admin added store credit', 'addCustomerModalVisible');
        },

        async adjustBalance(action, customerId, value, reason, modal, currencyId = null) {
            if (this.isSaving || !this.acl.can('store_credit.editor')) return;
            const amount = Number(value);
            if (!customerId || !Number.isFinite(amount) || amount <= 0) {
                this.createNotificationError({ message: 'Select a customer and enter a positive amount.' });
                return;
            }
            this.isSaving = true;
            try {
                await this.storeCreditApiService.adjust(action, customerId, amount, reason || 'Admin update', currencyId);
                this.createNotificationSuccess({ message: 'Store credit updated successfully.' });
                this[modal] = false;
                await this.fetchStoreCredits();
            } catch (error) {
                this.createNotificationError({ message: error.response?.data?.message || error.message || 'Could not update store credit.' });
            } finally {
                this.isSaving = false;
            }
        },

        navigateToCustomerHistory(storeCreditId, customerName, balance, customerId) {
            if (!storeCreditId) return this.createNotificationError({ title: 'Error', message: 'Invalid store credit ID.' });

            this.$router.push({
                name: 'store.credits.history',
                params: { id: storeCreditId },
                query: { name: customerName, balance, customerId },
            });
        },

        openDeleteModal(storeCredit) {
            this.selectedStoreCredit = { ...storeCredit };
            this.confirmDeleteModalVisible = true;
        },

        deleteStoreCredit() {
            if (this.isSaving || !this.acl.can('store_credit.deleter')) return;
            if (!this.selectedStoreCredit || !this.selectedStoreCredit.id) {
                return this.createNotificationError({ title: 'Error', message: 'Invalid store credit selection.' });
            }

            this.isSaving = true;
            return this.repository.delete(this.selectedStoreCredit.id, Shopware.Context.api)
                .then(() => {
                    this.createNotificationSuccess({ title: 'Success', message: 'Store credit deleted successfully!' });
                    this.confirmDeleteModalVisible = false;
                    this.fetchStoreCredits();
                })
                .catch((error) => {
                    console.error('Error deleting store credit:', error);
                    this.createNotificationError({ title: 'Error', message: 'Failed to delete store credit.' });
                    this.confirmDeleteModalVisible = false;
                })
                .finally(() => { this.isSaving = false; });
        },
    },
});
